func fanOutFanIn(ctx context.Context, input <-chan int, workers int) <-chan int {
    out := make(chan int)
    var wg sync.WaitGroup
    wg.Add(workers)

    for i := 0; i < workers; i++ {
        go func() {
            defer wg.Done()
            for v := range input {
                select {
                case out <- process(v):
                case <-ctx.Done():
                    return
                }
            }
        }()
    }

    go func() {
        wg.Wait()
        close(out)
    }()

    return out
}

func counter(start, end int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for i := start; i < end; i++ {
            out <- i
        }
    }()
    return out
}

for n := range counter(0, 5) {
    fmt.Println(n)   // 0 1 2 3 4
}

func generator(done <-chan struct{}, nums ...int) <-chan int {
    out := make(chan int)
    go func() {
        defer close(out)
        for _, n := range nums {
            select {
            case out <- n:
            case <-done:
                return
            }
        }
    }()
    return out
}

done := make(chan struct{})
out := generator(done, 1, 2, 3, 4, 5)
fmt.Println(<-out)   // 1
fmt.Println(<-out)   // 2
close(done)          // signal the generator to stop

func boundedParallel(items []Item, maxConcurrency int) {
    sem := make(chan struct{}, maxConcurrency)
    var wg sync.WaitGroup
    for _, item := range items {
        wg.Add(1)
        sem <- struct{}{}   // acquire (blocks if full)
        go func(item Item) {
            defer wg.Done()
            defer func() { <-sem }()   // release
            process(item)
        }(item)
    }
    wg.Wait()
}

func orDone(done <-chan struct{}, c <-chan T) <-chan T {
    out := make(chan T)
    go func() {
        defer close(out)
        for {
            select {
            case <-done:
                return
            case v, ok := <-c:
                if !ok {
                    return
                }
                select {
                case out <- v:
                case <-done:
                }
            }
        }
    }()
    return out
}

